SELECT DISTINCT SWS. ID, SWS.BADGE, SWS.WAGE_DATE, SS. NAME, SS.COMP_NAME, SS.DEP_NAME, SWS.CREATE_TIME, SWS.SIGN_STATUS FROM SMT_WAGE_SIGN SWS LEFT JOIN SMT_STAFF SS ON SWS.BADGE = SS.BADGE LEFT JOIN SMT_PARK_BU SPB ON SS.COMP_ID = SPB.COMP_ID
AND SWS.BADGE = #{query.badge}
AND SPB.PARK_ID = #{query.parkId}
AND SPB.PARK_ID IN
#{tempId}
AND SS.NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')
AND SWS.WAGE_DATE = #{query.wageDate}
AND SS.COMP_ID = #{query.compId}
AND SS.DEP_ID = #{query.depId}
AND SWS.SIGN_STATUS = #{query.signStatus}
AND SWS.CREATE_TIME >= TO_DATE(#{query.startTime}, 'yyyy-MM-dd')
AND SWS.CREATE_TIME < TO_DATE(#{query.endTime}, 'yyyy-MM-dd') + 1
ORDER BY SWS.CREATE_TIME DESC

SELECT
DISTINCT
SWS.id, SWS.SIGN_STATUS, SS.PHONE, SS.NAME
